//! 🧪️ Shared lossless serde_json words independently witness exact original dictionary and intrinsic equality.
use super::*;
use semio_framework_value::retained_clone::RetainedCloneSource;
fn grant()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:64,maximum_copy_bytes:16*1024*1024,maximum_capacity_bytes:16*1024*1024,maximum_release_bytes:16*1024*1024,maximum_depth:8192}}
fn corpus()->serde_json::Value{serde_json::from_str(include_str!("🧪️.json")).unwrap()}
fn run<S:QuestionEqualitySource>(a:S,b:S,cancel:Option<usize>)->(Option<bool>,usize){let(mut left,_)=RetainedCloneSource::admit_owned(a,(),grant()).unwrap_or_else(|_|panic!("left original source"));let(mut right,_)=RetainedCloneSource::admit_owned(b,(),grant()).unwrap_or_else(|_|panic!("right original source"));let mut cursor=BorrowedQuestionEquality::<S>::new();let mut capacity=0;let mut equal=None;let mut turns=0;for _ in 0..cancel.unwrap_or(1000000){for denied in [Default::default(),RetainedCloneGrant{maximum_copy_bytes:0,..grant()},RetainedCloneGrant{maximum_depth:0,..grant()},RetainedCloneGrant{maximum_items:0,..grant()}]{assert_eq!(cursor.advance(left.borrow(),right.borrow(),denied).unwrap().progress,Default::default());}let d=cursor.demand(left.borrow(),right.borrow(),grant().maximum_copy_bytes).unwrap();if d.capacity_bytes>0{assert_eq!(cursor.advance(left.borrow(),right.borrow(),RetainedCloneGrant{maximum_capacity_bytes:0,..grant()}).unwrap().progress,Default::default());}let step=cursor.advance(left.borrow(),right.borrow(),grant()).unwrap();assert!(step.progress.fits(grant()));capacity+=step.progress.retained_capacity_bytes;turns+=1;if step.equal.is_some(){equal=step.equal;break}}if cancel.is_none(){assert!(equal.is_some())}if turns>=2{cursor.verify_original(right.borrow()).unwrap();assert!(cursor.verify(left.borrow().project(7,|s|s),right.borrow()).is_err());assert!(cursor.verify(left.borrow(),right.borrow().project(7,|s|s)).is_err());}cursor.begin_close();let mut released=0;let mut closes=0;while !cursor.terminal_is_empty(){let d=cursor.close_demand(grant().maximum_copy_bytes).unwrap();if d.release_bytes>0{assert_eq!(cursor.close_step(RetainedCloneGrant{maximum_release_bytes:0,..grant()}).unwrap().progress(),Default::default());}let p=cursor.close_step(grant()).unwrap().progress();assert!(p.fits(grant()));released+=p.released_bytes;closes+=1;assert!(closes<1000000)}assert_eq!(capacity,released);while !right.terminal_is_empty(){right.close_step(grant()).unwrap();}while !left.terminal_is_empty(){left.close_step(grant()).unwrap();}(equal,turns)}
#[test]
fn shared_lossless_dictionary_and_individual_value_cases_match_serde_oracle(){for case in corpus()["cases"].as_array().unwrap(){let a:Option<QuestionDictionary>=serde_json::from_value(case["left"].clone()).unwrap();let b:Option<QuestionDictionary>=serde_json::from_value(case["right"].clone()).unwrap();let expected=case["equal"].as_bool().unwrap();assert_eq!(case["left"]==case["right"],expected);if let(Some(a),Some(b))=(&a,&b){if a.entries.len()==1&&b.entries.len()==1{let expected=case["left"]["entries"][0]["value"]==case["right"]["entries"][0]["value"];assert_eq!(run(a.entries[0].value.clone(),b.entries[0].value.clone(),None).0,Some(expected));}}assert_eq!(run(a,b,None).0,Some(expected),"{}",case["name"]);}}
fn deep(depth:usize)->DslValue{let mut value=DslValue::Null;for _ in 0..depth{value=DslValue::Object(vec![("q".into(),DslValue::Array(vec![value]))]);}value}
#[test]
fn deep_borrowed_intrinsic_frontiers_and_cancellation_release_every_page(){for cancel in [0,1,2,3,4,10,100,300]{run(deep(512),deep(512),Some(cancel));}assert_eq!(run(deep(512),deep(512),None).0,Some(true));let text="Ω🌍".repeat(8192);let a=Some(QuestionDictionary{entries:vec![super::super::QuestionDictionaryEntry{question_id:text.clone(),value:DslValue::String(text.clone())}]});let b=Some(QuestionDictionary{entries:vec![super::super::QuestionDictionaryEntry{question_id:text.clone(),value:DslValue::String(text)}]});let(equal,turns)=run(a,b,None);assert_eq!(equal,Some(true));assert!(turns>128);}
#[test]
fn source_issuer_substitution_is_rejected_while_original_aliases_remain_held(){let(mut a,_)=RetainedCloneSource::admit_owned(DslValue::Null,(),grant()).unwrap_or_else(|_|panic!("a"));let(mut b,_)=RetainedCloneSource::admit_owned(DslValue::Null,(),grant()).unwrap_or_else(|_|panic!("b"));let(mut swap,_)=RetainedCloneSource::admit_owned(DslValue::Null,(),grant()).unwrap_or_else(|_|panic!("swap"));let mut cursor=QuestionValueEqualityCursor::new();cursor.advance(a.borrow(),b.borrow(),grant()).unwrap();cursor.advance(a.borrow(),b.borrow(),grant()).unwrap();assert!(cursor.verify(a.borrow(),swap.borrow()).is_err());assert!(cursor.verify(swap.borrow(),b.borrow()).is_err());cursor.begin_close();while !cursor.terminal_is_empty(){cursor.close_step(grant()).unwrap();}for source in [&mut a,&mut b,&mut swap]{while !source.terminal_is_empty(){source.close_step(grant()).unwrap();}}}

#[test]
fn settled_original_value_pairs_rebind_into_the_same_funded_paged_workspace(){let mut cursor=QuestionValueEqualityCursor::new();assert!(cursor.ready_to_bind());assert!(cursor.begin_rebind().is_err());let mut capacity=0;let mut first_capacity=0;for row in 0..256{let(mut left,_)=RetainedCloneSource::admit_owned(DslValue::uint(row),(),grant()).unwrap_or_else(|_|panic!("left"));let(mut right,_)=RetainedCloneSource::admit_owned(DslValue::uint(row+row%2),(),grant()).unwrap_or_else(|_|panic!("right"));while cursor.result().is_none(){let step=cursor.advance(left.borrow(),right.borrow(),grant()).unwrap();capacity+=step.progress.retained_capacity_bytes;}assert_eq!(cursor.result(),Some(row%2==0));if row==0{first_capacity=capacity}else{assert_eq!(capacity,first_capacity)}cursor.begin_rebind().unwrap();assert!(cursor.demand(left.borrow(),right.borrow(),grant().maximum_copy_bytes).is_err());loop{assert_eq!(cursor.rebind_step(Default::default()).unwrap().progress(),Default::default());let step=cursor.rebind_step(grant()).unwrap();assert_eq!(step.progress().retained_capacity_bytes,0);assert_eq!(step.progress().released_bytes,0);if matches!(step,RetainedCloneStep::Complete(_)){break}}assert!(cursor.ready_to_bind());assert!(cursor.verify_original(right.borrow()).is_err());while !right.terminal_is_empty(){right.close_step(grant()).unwrap();}while !left.terminal_is_empty(){left.close_step(grant()).unwrap();}}cursor.begin_close();let mut released=0;while !cursor.terminal_is_empty(){released+=cursor.close_step(grant()).unwrap().progress().released_bytes;}assert_eq!(released,capacity);}

#[test]
fn cancellation_during_rebind_keeps_every_original_workspace_page_until_final_close(){for cut in [0,1,2,3,4,10,100,300]{let(mut left,_)=RetainedCloneSource::admit_owned(deep(32),(),grant()).unwrap_or_else(|_|panic!("left"));let(mut right,_)=RetainedCloneSource::admit_owned(DslValue::Null,(),grant()).unwrap_or_else(|_|panic!("right"));let mut cursor=QuestionValueEqualityCursor::new();let mut capacity=0;while cursor.result().is_none(){capacity+=cursor.advance(left.borrow(),right.borrow(),grant()).unwrap().progress.retained_capacity_bytes;}assert_eq!(cursor.result(),Some(false));cursor.begin_rebind().unwrap();for _ in 0..cut{if matches!(cursor.rebind_step(grant()).unwrap(),RetainedCloneStep::Complete(_)){break}}cursor.begin_close();let mut released=0;while !cursor.terminal_is_empty(){released+=cursor.close_step(grant()).unwrap().progress().released_bytes;}assert_eq!(released,capacity);while !right.terminal_is_empty(){right.close_step(grant()).unwrap();}while !left.terminal_is_empty(){left.close_step(grant()).unwrap();}}}
